mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.2) * p.xz;
  vec3 q = abs(p);
  float hull = max(q.x - 1.3, max(q.y - 0.4, q.z - 0.8)) - 0.05;
  float shield = length(p) - (1.6 + 0.1 * sin(time * 3.0) * bass);
  return min(hull, abs(shield) - 0.02);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.8, -3.6);
  vec3 rd = normalize(vec3(p, 1.6));
  rd.yz = rot(-0.2) * rd.yz;
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.02, 0.04, 0.08);
  if (t < 8.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.003, 0.0);
    vec3 n = normalize(vec3(map(pos+e.xyy)-map(pos-e.xyy), map(pos+e.yxy)-map(pos-e.yxy), map(pos+e.yyx)-map(pos-e.yyx)));
    vec3 l = normalize(vec3(1.0, 2.0, -1.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
    float rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    col = vec3(0.06, 0.1, 0.18) + diff * vec3(0.3, 0.6, 0.9) + spec * vec3(0.8, 0.9, 1.0) + rim * vec3(0.2, 0.8, 1.0);
  }
  col += glow * vec3(0.1, 0.7, 1.2) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
